-- Phase 3B canonical DML-only live verification; synthetic database-role facts.
-- No DDL, credentials, object bytes or customer changes. HTTP/Storage byte
-- acceptance is separate. All assertions and fixture writes roll back atomically.
BEGIN;
DO $live$
DECLARE v_passed integer:=0;v_results jsonb:='{}';v_result jsonb;v_failed boolean;v_safe boolean;
BEGIN
 IF EXISTS(SELECT 1 FROM public.people WHERE display_name LIKE 'Synthetic Phase3B Live %')
  OR EXISTS(SELECT 1 FROM public.organizations WHERE slug LIKE 'synthetic-phase3b-live-%')
  OR EXISTS(SELECT 1 FROM auth.users WHERE email LIKE '%@phase3b-live.example.invalid')
 THEN RAISE EXCEPTION 'Synthetic Phase3B live fixture collision';END IF;
 v_passed:=v_passed+1;
INSERT INTO auth.users(id,email,email_confirmed_at,is_anonymous)
SELECT (md5('boss-phase3b-live:'||('auth-'||label))::uuid),label||'@phase3b-live.example.invalid',CASE WHEN label='unconfirmed' THEN NULL ELSE now()-interval '1 day' END,label='anonymous'
FROM unnest(ARRAY['platform','admin-a','admin-b','registrar','finance','unit','coach','assistant','emergency','guardian','limited-guardian','unverified','household-only','outsider','expired','unconfirmed','anonymous']) label;
