FROM (VALUES
 ('platform','platform_administrator','platform',NULL::uuid,NULL::uuid,NULL::timestamptz),
 ('admin-a','organization_administrator','organization',(md5('boss-phase3b-live:'||('org-a'))::uuid),(md5('boss-phase3b-live:'||('org-a'))::uuid),NULL),
 ('admin-b','organization_administrator','organization',(md5('boss-phase3b-live:'||('org-b'))::uuid),(md5('boss-phase3b-live:'||('org-b'))::uuid),NULL),
 ('registrar','registrar','organization',(md5('boss-phase3b-live:'||('org-a'))::uuid),(md5('boss-phase3b-live:'||('org-a'))::uuid),NULL),
 ('finance','organization_finance','organization',(md5('boss-phase3b-live:'||('org-a'))::uuid),(md5('boss-phase3b-live:'||('org-a'))::uuid),NULL),
 ('unit','program_administrator','organization_unit',(md5('boss-phase3b-live:'||('unit-a'))::uuid),(md5('boss-phase3b-live:'||('org-a'))::uuid),NULL),
 ('coach','head_coach','team',(md5('boss-phase3b-live:'||('team-a'))::uuid),(md5('boss-phase3b-live:'||('org-a'))::uuid),NULL),
 ('assistant','assistant_coach','team',(md5('boss-phase3b-live:'||('team-a'))::uuid),(md5('boss-phase3b-live:'||('org-a'))::uuid),NULL),
 ('emergency','head_coach','team',(md5('boss-phase3b-live:'||('team-a'))::uuid),(md5('boss-phase3b-live:'||('org-a'))::uuid),NULL),
 ('expired','organization_finance','organization',(md5('boss-phase3b-live:'||('org-a'))::uuid),(md5('boss-phase3b-live:'||('org-a'))::uuid),now()-interval '1 hour')
) x(actor,role_key,scope_type,scope_id,organization_id,ends_at) JOIN public.roles r ON r.key=x.role_key;
