ons','achievement_definition_revisions','entity_achievements','achievement_recognitions','achievement_history','achievement_display_choices','award_nominations','award_decisions','achievement_competition_closures','achievement_refresh_work'))),false) THEN RAISE EXCEPTION 'Live assertion failed: %','historical 51 public tables';END IF;v_passed:=v_passed+1;
