artners.contract_approve','partners.catalog_review','partners.integration_activate','partners.revenue_report') AND key NOT LIKE 'games.%') AND (SELECT count(*)=239 FROM public.role_permissions rp JOIN public.permissions p ON p.id=rp.permission_id WHERE p.key NOT IN ('announcements.send','communications.manage','communications.send','communications.view','delivery_history.view','moderation.manage','notifications.manage','notifications.view','team_chat.send','team_chat.view','attendance.view','attendance.respond','attendance.manage','attendance.checkin','volunteers.view','volunteers.signup','volunteers.manage','volunteers.assign','competition.view','competition.manage','competition.policy_manage','standings.view','standings.manage','standings.rebuild','leaderboard.view','leaderboard.manage','leaderboard.rebuild','records.view','records.manage','records.rebuild','athlete_profiles.view','athlete_profiles.manage','athlete_profiles.verify','recruiting_showcases.view','recruiting_showcases.manage','recruiting_showcases.publish','achievement_definitions.manage','awards.issue','awards.approve','fundraising.view','fundraising.create','fundraising.manage','fundraising.publish','fundraising.financial_view','money_board.view','money_board.manage','boss_bucks.view','boss_bucks.manage','boss_bucks.financial_view','boss_bucks.policy_manage','boss_bucks.membership_view','boss_bucks.membership_manage','boss_bucks.product_manage','boss_bucks.inventory_manage','boss_bucks.fulfillment_manage','boss_bucks.payment_reverse','payments.refund','payments.provider_manage','settlements.view','settlements.manage','settlements.reconcile','merchants.view','merchants.manage','merchants.access_manage','merchant_locations.view','merchant_locations.manage','merchant_offers.view','merchant_offers.manage','merchant_redemptions.view','merchant_redemptions.manage','merchant_reviews.manage','merchant_sales.view','merchant_sales.manage','partners.view','partners.configure','partners.contract_approve','partners.catalog_review','partners.integration_activate','partners.revenue_report') AND p.key NOT LIKE 'games.%')),false) THEN RAISE EXCEPTION 'Live assertion failed: %','historical 21 roles 34 permissions 239 mappings';END IF;v_passed:=v_passed+1;
IF NOT coalesce(((SELECT NOT public AND file_size_limit=10485760 AND allowed_mime_types @> ARRAY['application/pdf','image/jpeg','image/png'] FROM storage.buckets WHERE id='boss-registration-documents')),false) THEN RAISE EXCEPTION 'Live assertion failed: %','private registration bucket constraints';END IF;v_passed:=v_passed+1;
DECLARE t text;denied boolean;action text;col text;BEGIN
 FOREACH t IN ARRAY ARRAY['registration_offerings','registration_form_versions','registration_waiver_versions','document_requirements','registration_offering_forms','registration_offering_waivers','registration_offering_documents','registration_fee_rules','registration_coupons','registrations','registration_form_answers','waiver_signatures','registration_documents','document_upload_intents','participant_emergency_records','charges','charge_adjustments','payments','payment_allocations','payment_plans','payment_installments'] LOOP
  IF NOT coalesce(((SELECT relrowsecurity FROM pg_catalog.pg_class WHERE oid=('public.'||t)::regclass)),false) THEN RAISE EXCEPTION 'Live assertion failed: %',t||' RLS enabled';END IF;v_passed:=v_passed+1;
  IF NOT coalesce((NOT has_table_privilege('anon','public.'||t,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE')),false) THEN RAISE EXCEPTION 'Live assertion failed: %',t||' no anonymous raw grant';END IF;v_passed:=v_passed+1;
  IF NOT coalesce((NOT has_table_privilege('authenticated','public.'||t,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE')),false) THEN RAISE EXCEPTION 'Live assertion failed: %',t||' no authenticated raw grant';END IF;v_passed:=v_passed+1;
  IF NOT coalesce((NOT has_table_privilege('service_role','public.'||t,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE')),false) THEN RAISE EXCEPTION 'Live assertion failed: %',t||' no service-role inherited grant';END IF;v_passed:=v_passed+1;
 END LOOP;
