-- Every sensitive evidence table is closed through both API roles. Immutable
-- triggers are additionally exercised as the trusted local owner: they protect
-- history independently of whether clients ever gain a raw table grant.
DECLARE t text;role_name text;action text;col text;statement text;BEGIN
 FOREACH role_name IN ARRAY ARRAY['anon','authenticated'] LOOP
  EXECUTE format('SET LOCAL ROLE %I',role_name);
  FOR t IN SELECT tablename FROM pg_catalog.pg_tables WHERE schemaname='public' AND tablename=ANY(ARRAY['registration_offerings','registration_form_versions','registration_waiver_versions','document_requirements','registration_offering_forms','registration_offering_waivers','registration_offering_documents','registration_fee_rules','registration_coupons','registrations','registration_form_answers','waiver_signatures','registration_documents','document_upload_intents','participant_emergency_records','charges','charge_adjustments','payments','payment_allocations','payment_plans','payment_installments']) LOOP
   SELECT attname INTO col FROM pg_catalog.pg_attribute WHERE attrelid=('public.'||t)::regclass AND attnum>0 AND NOT attisdropped ORDER BY attnum LIMIT 1;
   FOREACH action IN ARRAY ARRAY['SELECT','INSERT','UPDATE','DELETE'] LOOP
    statement:=CASE action WHEN 'SELECT' THEN format('SELECT count(*) FROM public.%I WHERE false',t) WHEN 'INSERT' THEN format('INSERT INTO public.%I DEFAULT VALUES',t) WHEN 'UPDATE' THEN format('UPDATE public.%I SET %I=%I WHERE false',t,col,col) ELSE format('DELETE FROM public.%I WHERE false',t) END;
    v_failed:=false;v_safe:=false;BEGIN EXECUTE statement; EXCEPTION WHEN OTHERS THEN IF SQLSTATE=ANY(ARRAY['42501']) THEN v_failed:=true;v_safe:=length(SQLERRM)<160 AND SQLERRM !~* '(constraint|relation|column|password|token|stack|SELECT|INSERT|UPDATE|DELETE)';ELSE RAISE EXCEPTION 'Live denial failed: %; unexpected state %',role_name||' actual '||action||' denied '||t,SQLSTATE;END IF;END;
IF NOT coalesce((v_failed),false) THEN RAISE EXCEPTION 'Live assertion failed: %',role_name||' actual '||action||' denied '||t;END IF;v_passed:=v_passed+1;
   END LOOP;
  END LOOP;
  EXECUTE 'RESET ROLE';
 END LOOP;
END;
