v_failed:=false;v_safe:=false;BEGIN PERFORM public.boss_registration_mutate(md5('boss-phase3b-live:request-'||('guardian renewal does not create reviewer authority'))::uuid,jsonb_build_object('operation','document.review','input',jsonb_build_object('document_id',((v_results->('physical document'))->>'resource_id')::uuid,'expected_version',(SELECT (result->>'version')::bigint FROM (SELECT key AS label,value AS result FROM jsonb_each(v_results)) stored WHERE label='naturally expired physical renewal complete'),'status','approved','reason','Synthetic denied self approval'))); EXCEPTION WHEN OTHERS THEN IF SQLSTATE=ANY(ARRAY['PT403']) THEN v_failed:=true;v_safe:=length(SQLERRM)<160 AND SQLERRM !~* '(constraint|relation|column|password|token|stack|SELECT|INSERT|UPDATE|DELETE)';ELSE RAISE EXCEPTION 'Live denial failed: %; unexpected state %','guardian renewal does not create reviewer authority',SQLSTATE;END IF;END;
IF NOT coalesce((v_failed),false) THEN RAISE EXCEPTION 'Live assertion failed: %','guardian renewal does not create reviewer authority';END IF;v_passed:=v_passed+1;
IF NOT coalesce((v_safe),false) THEN RAISE EXCEPTION 'Live assertion failed: %','guardian renewal does not create reviewer authority'||' safe error';END IF;v_passed:=v_passed+1;
PERFORM set_config('request.jwt.claim.sub','',true);PERFORM set_config('request.jwt.claim','',true);
PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',md5('boss-phase3b-live:auth-'||('admin-a'))::uuid,'role','authenticated','is_anonymous',false,'session_id',md5('boss-phase3b-live:session-'||('admin-a'))::uuid,'user_metadata',jsonb_build_object('is_admin',true,'role','super_administrator'))::text,true);
v_result:=public.boss_registration_mutate(md5('boss-phase3b-live:request-'||('naturally expired physical authorized renewed review'))::uuid,jsonb_build_object('operation','document.review','input',jsonb_build_object('document_id',((v_results->('physical document'))->>'resource_id')::uuid,'expected_version',(SELECT (result->>'version')::bigint FROM (SELECT key AS label,value AS result FROM jsonb_each(v_results)) stored WHERE label='naturally expired physical renewal complete'),'status','approved','reason','Synthetic reviewed renewed physical','expires_on',current_date+365)));
IF NOT coalesce((jsonb_typeof(v_result)='object'),false) THEN RAISE EXCEPTION 'Live assertion failed: %','naturally expired physical authorized renewed review';END IF;v_passed:=v_passed+1;
v_results:=v_results||jsonb_build_object('naturally expired physical authorized renewed review',v_result);
PERFORM set_config('request.jwt.claim.sub','',true);PERFORM set_config('request.jwt.claim','',true);
PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',md5('boss-phase3b-live:auth-'||('guardian'))::uuid,'role','authenticated','is_anonymous',false,'session_id',md5('boss-phase3b-live:session-'||('guardian'))::uuid,'user_metadata',jsonb_build_object('is_admin',true,'role','super_administrator'))::text,true);
IF NOT coalesce((public.boss_registration_read(jsonb_build_object('registration_id',((v_results->('child one draft'))->>'resource_id')::uuid))->'detail'->>'document_status'='approved' AND EXISTS(SELECT 1 FROM jsonb_array_elements(public.boss_registration_read('{}')->'registrations') r WHERE r->>'id'=((v_results->('child one draft'))->>'resource_id')::uuid::text AND r->>'document_status'='approved')),false) THEN RAISE EXCEPTION 'Live assertion failed: %','reviewed renewed physical current status is approved in detail and list';END IF;v_passed:=v_passed+1;
EXECUTE 'RESET ROLE';
IF NOT coalesce(((SELECT count(*)=2 FROM storage.objects WHERE bucket_id='boss-registration-documents' AND name IN((SELECT result->>'object_name' FROM (SELECT key AS label,value AS result FROM jsonb_each(v_results)) stored WHERE label='physical upload intent'),(SELECT result->>'object_name' FROM (SELECT key AS label,value AS result FROM jsonb_each(v_results)) stored WHERE label='naturally expired physical renewal intent'))) AND EXISTS(SELECT 1 FROM boss_private.registration_document_history WHERE document_id=((v_results->('physical document'))->>'resource_id')::uuid AND version=4 AND snapshot->>'status'='approved') AND EXISTS(SELECT 1 FROM public.audit_events WHERE request_id=(md5('boss-phase3b-live:'||('request-naturally expired physical renewal intent'))::uuid) AND action='document.intent')),false) THEN RAISE EXCEPTION 'Live assertion failed: %','renewal retains both isolated metadata versions and all history';END IF;v_passed:=v_passed+1;


IF NOT (SELECT count(*)=3 AND bool_and(cmd IN('INSERT','SELECT')) AND bool_and(roles=ARRAY['authenticated']::name[]) FROM pg_catalog.pg_policies WHERE schemaname='storage' AND policyname IN('boss_registration_document_upload','boss_registration_document_download','boss_registration_document_upload_returning')) THEN RAISE EXCEPTION 'Storage canonical policies changed';END IF;v_passed:=v_passed+1;
IF EXISTS(SELECT 1 FROM pg_catalog.pg_policies WHERE schemaname='storage' AND tablename='objects' AND cmd IN('ALL','UPDATE','DELETE') AND (coalesce(qual,'')||coalesce(with_check,'')) LIKE '%boss-registration-documents%') THEN RAISE EXCEPTION 'Private registration object replacement policy opened';END IF;v_passed:=v_passed+1;
IF has_function_privilege('anon','public.boss_registration_read(jsonb)','EXECUTE') OR has_function_privilege('service_role','public.boss_registration_read(jsonb)','EXECUTE') OR has_function_privilege('service_role','public.boss_registration_mutate(uuid,jsonb)','EXECUTE') THEN RAISE EXCEPTION 'Private caller RPC grants opened';END IF;v_passed:=v_passed+1;
IF v_passed<>730 THEN RAISE EXCEPTION 'Phase3B expected assertion count changed';END IF;
PERFORM set_config('boss.phase3b_live_assertions',v_passed::text,true);
END $live$;
SELECT current_setting('boss.phase3b_live_assertions')::integer AS passed_assertions;
ROLLBACK;
SELECT 730 AS passed_assertions,
 (SELECT count(*) FROM public.people WHERE display_name LIKE 'Synthetic Phase3B Live %') AS synthetic_people_remaining,
 (SELECT count(*) FROM public.organizations WHERE slug LIKE 'synthetic-phase3b-live-%') AS synthetic_organizations_remaining,
 (SELECT count(*) FROM auth.users WHERE email LIKE '%@phase3b-live.example.invalid') AS synthetic_auth_users_remaining,
 (SELECT count(*) FROM public.registrations WHERE submitted_by_person_id=md5('boss-phase3b-live:guardian')::uuid) AS synthetic_registrations_remaining,
 (SELECT count(*) FROM storage.objects WHERE name LIKE md5('boss-phase3b-live:org-a')::uuid::text||'/%') AS synthetic_objects_remaining,
 (SELECT count(*) FROM public.audit_events WHERE actor_person_id IN(SELECT md5('boss-phase3b-live:'||actor)::uuid FROM unnest(ARRAY['platform','admin-a','admin-b','registrar','finance','unit','coach','assistant','emergency','guardian','limited-guardian','unverified','household-only','outsider','expired','unconfirmed','anonymous']) actor)) AS synthetic_audits_remaining,
 (SELECT count(*) FROM boss_private.registration_operation_receipts WHERE actor_person_id IN(SELECT md5('boss-phase3b-live:'||actor)::uuid FROM unnest(ARRAY['platform','admin-a','admin-b','registrar','finance','unit','coach','assistant','emergency','guardian','limited-guardian','unverified','household-only','outsider','expired','unconfirmed','anonymous']) actor)) AS synthetic_receipts_remaining;
